212|## Loading GLTF Animations
213|
214|Most common source of skeletal animations.
215|
216|```javascript
217|import { GLTFLoader } from "three/examples/jsm/loaders/GLTFLoader.js";
218|
219|const loader = new GLTFLoader();
220|loader.load("model.glb", (gltf) => {
221|  const model = gltf.scene;
222|  scene.add(model);
223|
224|  // Create mixer
225|  const mixer = new THREE.AnimationMixer(model);
226|
227|  // Get all clips
228|  const clips = gltf.animations;
229|  console.log(
230|    "Available animations:",
231|    clips.map((c) => c.name),
232|  );
233|
234|  // Play first animation
235|  if (clips.length > 0) {
236|    const action = mixer.clipAction(clips[0]);
237|    action.play();
238|  }
239|
240|  // Play specific animation by name
241|  const walkClip = THREE.AnimationClip.findByName(clips, "Walk");
242|  if (walkClip) {
243|    mixer.clipAction(walkClip).play();
244|  }
245|
246|  // Store mixer for update loop
247|  window.mixer = mixer;
248|});
249|
250|// Animation loop
251|function animate() {
252|  const delta = clock.getDelta();
253|  if (window.mixer) window.mixer.update(delta);
254|
255|  requestAnimationFrame(animate);
256|  renderer.render(scene, camera);
257|}
258|```
