import * as THREE from 'three';

// Procedural surfing pelican standing on a surfboard, facing +X.
// createSurfer() returns { group, update(t) }; the caller samples the
// shared wave function so the rider sits on the animated ocean surface.

const MAT = {
  body: new THREE.MeshStandardMaterial({ color: 0xd9d2c4, roughness: 0.8 }),
  wing: new THREE.MeshStandardMaterial({ color: 0xc9c1b1, roughness: 0.85 }),
  wingTip: new THREE.MeshStandardMaterial({ color: 0x6f675c, roughness: 0.9 }),
  white: new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.7 }),
  crown: new THREE.MeshStandardMaterial({ color: 0xf3c14f, roughness: 0.7 }),
  beak: new THREE.MeshStandardMaterial({ color: 0xf29a3e, roughness: 0.55 }),
  nail: new THREE.MeshStandardMaterial({ color: 0xc96a24, roughness: 0.6 }),
  pouch: new THREE.MeshStandardMaterial({ color: 0xefa08b, roughness: 0.75 }),
  eye: new THREE.MeshStandardMaterial({ color: 0x14100c, roughness: 0.25 }),
  glint: new THREE.MeshBasicMaterial({ color: 0xffffff }),
  foot: new THREE.MeshStandardMaterial({ color: 0xe8823c, roughness: 0.7 }),
  board: new THREE.MeshStandardMaterial({ color: 0xff5a5f, roughness: 0.45 }),
  stripe: new THREE.MeshStandardMaterial({ color: 0xfff3df, roughness: 0.5 }),
};

function mesh(geo, mat, x = 0, y = 0, z = 0) {
  const m = new THREE.Mesh(geo, mat);
  m.position.set(x, y, z);
  m.castShadow = true;
  return m;
}

function buildBoard() {
  const board = new THREE.Group();

  const deckGeo = new THREE.CapsuleGeometry(0.42, 2.4, 6, 14);
  deckGeo.rotateZ(Math.PI / 2); // long axis along X
  const deck = mesh(deckGeo, MAT.board, 0, 0.16, 0);
  deck.scale.set(1, 0.32, 1);
  board.add(deck);

  board.add(mesh(new THREE.BoxGeometry(1.7, 0.03, 0.2), MAT.stripe, 0, 0.3, 0));

  const finGeo = new THREE.ConeGeometry(0.14, 0.4, 4);
  const fin = mesh(finGeo, MAT.stripe, -1.15, -0.05, 0);
  fin.rotation.x = Math.PI; // point down
  fin.scale.set(1, 1, 0.3);
  board.add(fin);

  board.rotation.z = 0.05; // nose slightly up
  board.position.y = 0.05;
  return board;
}

// side: +1 for the +Z wing, -1 for the -Z wing.
function buildWing(side) {
  const wing = new THREE.Group();
  wing.position.set(0.02, 1.02, side * 0.42);

  const inner = mesh(new THREE.SphereGeometry(0.5, 12, 8), MAT.wing, 0, 0, side * 0.45);
  inner.scale.set(0.62, 0.1, 1.05);
  wing.add(inner);

  const outer = new THREE.Group();
  outer.position.z = side * 0.9;
  const outerGeo = new THREE.ConeGeometry(0.3, 1.05, 7);
  const outerMesh = mesh(outerGeo, MAT.wing, 0, 0, side * 0.5);
  outerMesh.rotation.x = (side * Math.PI) / 2; // tip points outward
  outerMesh.scale.set(0.9, 1, 0.28); // flatten vertically
  outer.add(outerMesh);

  const tipGeo = new THREE.ConeGeometry(0.16, 0.5, 7);
  const tip = mesh(tipGeo, MAT.wingTip, 0, 0, side * 1.05);
  tip.rotation.x = (side * Math.PI) / 2;
  tip.scale.set(0.9, 1, 0.3);
  outer.add(tip);

  wing.add(outer);
  wing.rotation.y = -side * 0.18; // swept slightly back
  return { wing, outer };
}

function buildHead() {
  const head = new THREE.Group();
  head.position.set(0.62, 1.52, 0);

  head.add(mesh(new THREE.SphereGeometry(0.3, 18, 14), MAT.white));

  const crown = mesh(new THREE.SphereGeometry(0.2, 14, 10), MAT.crown, -0.07, 0.22, 0);
  crown.scale.set(1.05, 0.55, 0.95);
  head.add(crown);

  for (const side of [1, -1]) {
    head.add(mesh(new THREE.SphereGeometry(0.06, 10, 8), MAT.eye, 0.17, 0.07, side * 0.205));
    const glint = mesh(new THREE.SphereGeometry(0.02, 6, 6), MAT.glint, 0.205, 0.1, side * 0.235);
    glint.castShadow = false;
    head.add(glint);
  }

  // Long bill with a hanging pouch, pivoting at the face.
  const beak = new THREE.Group();
  beak.position.set(0.24, -0.03, 0);
  const upperGeo = new THREE.ConeGeometry(0.1, 1.3, 12);
  const upper = mesh(upperGeo, MAT.beak, 0.65, -0.02, 0);
  upper.rotation.z = -Math.PI / 2; // point forward (+X)
  beak.add(upper);

  const nailGeo = new THREE.ConeGeometry(0.045, 0.12, 8);
  const nail = mesh(nailGeo, MAT.nail, 1.3, -0.03, 0);
  nail.rotation.z = -Math.PI / 2 - 0.3; // small downward hook
  beak.add(nail);

  const pouch = mesh(new THREE.SphereGeometry(0.3, 14, 10), MAT.pouch, 0.62, -0.26, 0);
  pouch.scale.set(1.6, 0.85, 0.6);
  beak.add(pouch);

  beak.rotation.z = -0.1;
  head.add(beak);
  return { head, beak, pouch };
}

export function createSurfer() {
  const group = new THREE.Group();
  group.add(buildBoard());

  const pelican = new THREE.Group();
  pelican.position.y = 0.3; // standing on the deck
  group.add(pelican);

  // Feet planted in a surf stance, side by side.
  const footGeo = new THREE.SphereGeometry(0.16, 10, 8);
  for (const side of [1, -1]) {
    const foot = mesh(footGeo, MAT.foot, -0.05, 0.05, side * 0.2);
    foot.scale.set(1.6, 0.35, 1.0);
    pelican.add(foot);
    pelican.add(mesh(new THREE.CylinderGeometry(0.05, 0.06, 0.35, 8), MAT.foot, -0.05, 0.22, side * 0.2));
  }

  const body = mesh(new THREE.SphereGeometry(0.62, 20, 16), MAT.body, 0, 0.78, 0);
  body.scale.set(1.15, 0.95, 0.85);
  body.rotation.z = -0.1;
  pelican.add(body);

  const tail = mesh(new THREE.ConeGeometry(0.2, 0.5, 7), MAT.wing, -0.68, 0.85, 0);
  tail.scale.set(1, 1, 1.6);
  tail.rotation.z = 1.25; // point back and slightly up
  pelican.add(tail);

  const neck = mesh(new THREE.CylinderGeometry(0.15, 0.21, 0.75, 12), MAT.white, 0.42, 1.15, 0);
  neck.rotation.z = -0.45;
  pelican.add(neck);

  const { head, beak, pouch } = buildHead();
  pelican.add(head);

  const right = buildWing(1);
  const left = buildWing(-1);
  pelican.add(right.wing);
  pelican.add(left.wing);

  function update(t, heightAt) {
    // Ride the actual wave surface: height from the crest, tilt from slope.
    const slopeX = (heightAt(0.9, 0, t) - heightAt(-0.9, 0, t)) / 1.8;
    const slopeZ = (heightAt(0, 0.9, t) - heightAt(0, -0.9, t)) / 1.8;
    const pitch = Math.atan(slopeX) * 0.8 + Math.sin(t * 0.7) * 0.02;
    const roll = -Math.atan(slopeZ) * 0.8 + Math.sin(t * 0.23 + 0.7) * 0.06;
    group.rotation.set(roll, Math.sin(t * 0.21) * 0.12, pitch);
    group.position.y = heightAt(0, 0, t) - 0.02 + Math.sin(t * 1.7) * 0.04;

    // Crouched body leans into the carve, head scans the wave.
    pelican.rotation.x = Math.sin(t * 0.21 - 0.7) * 0.1;
    pelican.rotation.z = -0.02 + Math.sin(t * 0.9) * 0.02;
    head.rotation.y = Math.sin(t * 0.45) * 0.38;
    head.rotation.x = Math.sin(t * 0.8) * 0.06;

    // Bill bobs, pouch jiggles.
    beak.rotation.z = -0.1 + Math.sin(t * 2.1) * 0.035;
    pouch.scale.y = 0.85 * (1 + Math.sin(t * 3.0) * 0.07);
    pouch.position.y = -0.26 + Math.sin(t * 2.1 - 0.4) * 0.02;

    // Wings held out for balance, adjusting against the roll.
    const common = 0.2 + Math.sin(t * 1.35) * 0.07;
    const diff =
      THREE.MathUtils.clamp(-roll * 1.6, -0.3, 0.3) + Math.sin(t * 0.9 + 1.0) * 0.06;
    right.wing.rotation.x = -(common + diff);
    left.wing.rotation.x = common - diff;
    const lag = 0.1 + Math.sin(t * 1.35 - 0.6) * 0.09;
    right.outer.rotation.x = -lag;
    left.outer.rotation.x = lag;

    tail.rotation.y = Math.sin(t * 2.0) * 0.12;
  }

  return { group, update };
}

import * as THREE from 'three';

// Animated ocean: a rolling swell the surfer rides, a curling breaker
// behind them, foam on its lip, whitewater at its foot, and a wake
// trailing the board. Everything is procedural geometry.

// Shared wave surface. Swell travels toward -X so the rider, facing +X,
// appears to move forward through the water.
export function waveHeight(x, z, t) {
  return (
    0.34 * Math.sin(x * 0.32 + t * 1.05) * Math.cos(z * 0.28 + t * 0.65) +
    0.17 * Math.sin(x * 0.66 - t * 1.5 + z * 0.42) +
    0.09 * Math.sin(z * 1.05 + t * 2.1 + x * 0.23)
  );
}

function smoothstep(a, b, x) {
  const t = THREE.MathUtils.clamp((x - a) / (b - a), 0, 1);
  return t * t * (3 - 2 * t);
}

// Deterministic pseudo-random so the foam layout is stable.
function mulberry32(seed) {
  let s = seed >>> 0;
  return () => {
    s |= 0;
    s = (s + 0x6d2b79f5) | 0;
    let v = Math.imul(s ^ (s >>> 15), 1 | s);
    v = (v + Math.imul(v ^ (v >>> 7), 61 | v)) ^ v;
    return ((v ^ (v >>> 14)) >>> 0) / 4294967296;
  };
}

const FOAM_MAT = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.9 });
const STREAK_MAT = new THREE.MeshStandardMaterial({
  color: 0xffffff,
  roughness: 1,
  transparent: true,
  opacity: 0.85,
});

const WAVE_POS = new THREE.Vector3(0, 2.3, -7);
const WAVE_W = 36;
const WAVE_H = 7.5;
const CURL = 4.3;

// Static curl of the breaker face: yn runs 0 (foot) to 1 (lip).
function curlOffset(bx, yn) {
  const s = smoothstep(0.3, 1.0, yn);
  return CURL * Math.pow(s, 1.6) * (1 + 0.06 * Math.sin(bx * 0.5));
}

export function createOcean(scene) {
  // --- Rolling swell ---
  const oceanGeo = new THREE.PlaneGeometry(170, 170, 100, 100);
  oceanGeo.rotateX(-Math.PI / 2);
  const ocean = new THREE.Mesh(
    oceanGeo,
    new THREE.MeshStandardMaterial({
      color: 0x1b6da3,
      roughness: 0.6,
      metalness: 0.05,
      flatShading: true,
    }),
  );
  ocean.receiveShadow = true;
  scene.add(ocean);
  const oceanPos = oceanGeo.attributes.position;

  // --- Far sea disc stretching to the horizon ---
  const farGeo = new THREE.CircleGeometry(400, 48);
  farGeo.rotateX(-Math.PI / 2);
  const far = new THREE.Mesh(
    farGeo,
    new THREE.MeshStandardMaterial({ color: 0x2e82ac, roughness: 1 }),
  );
  far.position.y = -0.45;
  scene.add(far);

  // --- Curling breaker ---
  const wallGeo = new THREE.PlaneGeometry(WAVE_W, WAVE_H, 64, 14);
  const wall = new THREE.Mesh(
    wallGeo,
    new THREE.MeshStandardMaterial({
      color: 0x1f9db4,
      roughness: 0.4,
      metalness: 0.05,
      transparent: true,
      opacity: 0.93,
      side: THREE.DoubleSide,
      flatShading: true,
    }),
  );
  wall.position.copy(WAVE_POS);
  wall.receiveShadow = true;
  scene.add(wall);
  const wallPos = wallGeo.attributes.position;
  const wallBase = wallPos.array.slice();

  // --- Foam: lip puffs, spilling puffs, whitewater, wake churn ---
  const rng = mulberry32(7);
  const puffGeo = new THREE.SphereGeometry(1, 8, 6);
  const puffs = []; // { m, bx, by, bz, sx, sy, sz, phase, kind }

  function addPuff(x, y, z, sx, sy, sz, kind) {
    const m = new THREE.Mesh(puffGeo, FOAM_MAT);
    m.position.set(x, y, z);
    m.scale.set(sx, sy, sz);
    scene.add(m);
    puffs.push({ m, bx: x, by: y, bz: z, sx, sy, sz, phase: rng() * Math.PI * 2, kind });
  }

  for (let i = 0; i < 30; i++) {
    const bx = -16.5 + (i * 33) / 29 + (rng() - 0.5) * 0.8;
    addPuff(
      bx,
      WAVE_POS.y + WAVE_H / 2 + (rng() - 0.5) * 0.4,
      WAVE_POS.z + curlOffset(bx, 1) + (rng() - 0.5) * 0.5,
      0.5 + rng() * 0.5,
      0.35 + rng() * 0.3,
      0.45 + rng() * 0.4,
      'lip',
    );
  }
  for (let i = 0; i < 16; i++) {
    const bx = -15 + rng() * 30;
    addPuff(
      bx,
      WAVE_POS.y + 2.6 + (rng() - 0.5) * 0.5,
      WAVE_POS.z + curlOffset(bx, 0.85) + 0.3,
      0.4 + rng() * 0.4,
      0.3 + rng() * 0.25,
      0.4 + rng() * 0.3,
      'spill',
    );
  }
  for (let i = 0; i < 14; i++) {
    addPuff(
      -16 + rng() * 32,
      0.5,
      -5.2 + rng() * 1.5,
      1.6 + rng(),
      0.22,
      0.9 + rng() * 0.5,
      'wash',
    );
  }
  for (let i = 0; i < 6; i++) {
    const s = 0.3 + rng() * 0.25;
    addPuff(-1.4 - rng() * 2.2, 0.2, (rng() - 0.5) * 0.6, s, s * 0.55, s, 'churn');
  }

  // --- Wake streaks fanning out behind the board ---
  const streaks = [];
  for (const side of [1, -1]) {
    const s = new THREE.Mesh(new THREE.BoxGeometry(4.2, 0.05, 0.4), STREAK_MAT);
    s.position.set(-3.2, 0.2, side * 0.85);
    s.rotation.y = side * 0.12;
    scene.add(s);
    streaks.push({ m: s, z: side * 0.85 });
  }

  function update(t) {
    // Swell follows the shared wave function.
    for (let i = 0; i < oceanPos.count; i++) {
      oceanPos.setY(i, waveHeight(oceanPos.getX(i), oceanPos.getZ(i), t));
    }
    oceanPos.needsUpdate = true;
    oceanGeo.computeVertexNormals();

    // Breaker face: static curl plus a lively ripple.
    for (let i = 0; i < wallPos.count; i++) {
      const bx = wallBase[i * 3];
      const by = wallBase[i * 3 + 1];
      const yn = (by + WAVE_H / 2) / WAVE_H;
      const ripple =
        0.14 * Math.sin(bx * 1.15 + t * 2.1) * yn + 0.08 * Math.sin(bx * 2.3 - t * 3.0) * yn;
      wallPos.setZ(i, curlOffset(bx, yn) + ripple);
      wallPos.setY(i, by + 0.12 * Math.sin(bx * 0.8 + t * 1.6) * yn);
    }
    wallPos.needsUpdate = true;
    wallGeo.computeVertexNormals();

    for (const p of puffs) {
      const w = 1 + 0.12 * Math.sin(t * 3.2 + p.phase);
      p.m.scale.set(p.sx * w, p.sy * (2 - w), p.sz * w);
      if (p.kind === 'lip') {
        p.m.position.y = p.by + 0.12 * Math.sin(t * 2.4 + p.phase * 1.3);
      } else if (p.kind === 'spill') {
        // Foam spilling down the face of the wave.
        const c = (t * 0.35 + p.phase) % 1;
        p.m.position.z = p.bz + c * 1.6;
        p.m.position.y = p.by - c * 1.1 + 0.06 * Math.sin(t * 5 + p.phase * 7);
      } else if (p.kind === 'wash') {
        // Whitewater drifting past with the current.
        let x = p.bx - t * 0.7;
        x = ((((x + 17) % 34) + 34) % 34) - 17;
        p.m.position.x = x;
        p.m.position.y = waveHeight(x, p.bz, t) + 0.15;
      } else {
        // Churn hugging the surface behind the board.
        p.m.position.y = waveHeight(p.bx, p.bz, t) + 0.12;
      }
    }

    for (const s of streaks) {
      s.m.position.y = waveHeight(-3.2, s.z, t) + 0.12;
    }
  }

  return { update };
}

import * as THREE from 'three';

// Sky dome with a gradient + sun glow shader, drifting low-poly clouds,
// and two distant gulls soaring in slow circles. All procedural.

const SUN_DIR = new THREE.Vector3(10, 14, 7).normalize();

function buildSkyDome() {
  const geo = new THREE.SphereGeometry(230, 24, 16);
  const mat = new THREE.ShaderMaterial({
    side: THREE.BackSide,
    depthWrite: false,
    uniforms: {
      topColor: { value: new THREE.Color(0x2f7fc9) },
      midColor: { value: new THREE.Color(0x8fd4ec) },
      botColor: { value: new THREE.Color(0xfdf1dc) },
      sunDir: { value: SUN_DIR },
    },
    vertexShader: `
      varying vec3 vDir;
      void main() {
        vDir = normalize(position);
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
      }
    `,
    fragmentShader: `
      varying vec3 vDir;
      uniform vec3 topColor;
      uniform vec3 midColor;
      uniform vec3 botColor;
      uniform vec3 sunDir;
      void main() {
        float h = clamp(normalize(vDir).y, -1.0, 1.0);
        vec3 col = mix(botColor, midColor, smoothstep(0.0, 0.25, h));
        col = mix(col, topColor, smoothstep(0.2, 0.75, h));
        col = mix(vec3(0.85, 0.93, 0.94), col, smoothstep(-0.15, 0.02, h));
        float s = max(dot(normalize(vDir), normalize(sunDir)), 0.0);
        col += vec3(1.0, 0.9, 0.75) * (pow(s, 800.0) * 1.2 + pow(s, 10.0) * 0.18);
        gl_FragColor = vec4(col, 1.0);
      }
    `,
  });
  return new THREE.Mesh(geo, mat);
}

function buildCloud(seed) {
  let s = seed >>> 0;
  const rng = () => {
    s |= 0;
    s = (s + 0x6d2b79f5) | 0;
    let v = Math.imul(s ^ (s >>> 15), 1 | s);
    v = (v + Math.imul(v ^ (v >>> 7), 61 | v)) ^ v;
    return ((v ^ (v >>> 14)) >>> 0) / 4294967296;
  };
  const mat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 1, flatShading: true });
  const cloud = new THREE.Group();
  const n = 4 + Math.floor(rng() * 3);
  for (let i = 0; i < n; i++) {
    const r = 1.2 + rng() * 1.6;
    const puff = new THREE.Mesh(new THREE.SphereGeometry(r, 9, 7), mat);
    puff.position.set((i - n / 2) * 2.0 + (rng() - 0.5), (rng() - 0.5) * 0.8, (rng() - 0.5) * 1.6);
    puff.scale.y = 0.55;
    cloud.add(puff);
  }
  return cloud;
}

function buildGull() {
  const mat = new THREE.MeshStandardMaterial({ color: 0x3a4750, roughness: 0.9 });
  const gull = new THREE.Group();
  const bodyGeo = new THREE.SphereGeometry(0.18, 8, 6);
  const body = new THREE.Mesh(bodyGeo, mat);
  body.scale.set(1.8, 0.5, 0.5);
  gull.add(body);
  const wings = [];
  for (const side of [1, -1]) {
    const pivot = new THREE.Group();
    const w = new THREE.Mesh(new THREE.BoxGeometry(0.08, 0.02, 0.55), mat);
    w.position.z = side * 0.32;
    pivot.add(w);
    gull.add(pivot);
    wings.push({ pivot, side });
  }
  return { gull, wings };
}

export function createSky(scene) {
  scene.add(buildSkyDome());

  const clouds = [];
  const cloudDefs = [
    { x: -30, y: 17, z: -28, s: 1.4, v: 0.45 },
    { x: 8, y: 21, z: -38, s: 1.9, v: 0.3 },
    { x: 38, y: 15, z: -20, s: 1.1, v: 0.55 },
    { x: -8, y: 19, z: 22, s: 1.3, v: 0.4 },
  ];
  cloudDefs.forEach((d, i) => {
    const c = buildCloud(100 + i * 17);
    c.position.set(d.x, d.y, d.z);
    c.scale.setScalar(d.s);
    scene.add(c);
    clouds.push({ c, v: d.v });
  });

  const gulls = [
    { ...buildGull(), cx: -6, cy: 9, cz: -10, r: 9, w: 0.14, p: 0 },
    { ...buildGull(), cx: 7, cy: 11, cz: -14, r: 12, w: -0.1, p: 2.4 },
  ];
  for (const g of gulls) scene.add(g.gull);

  function update(t, dt) {
    for (const { c, v } of clouds) {
      c.position.x -= dt * v;
      if (c.position.x < -70) c.position.x = 70;
    }
    for (const g of gulls) {
      const a = g.w * t + g.p;
      const x = g.cx + g.r * Math.cos(a);
      const z = g.cz + g.r * 0.6 * Math.sin(a);
      g.gull.position.set(x, g.cy + 0.5 * Math.sin(2 * a), z);
      // Face along the direction of travel.
      const vx = -Math.sin(a) * Math.sign(g.w);
      const vz = 0.6 * Math.cos(a) * Math.sign(g.w);
      g.gull.rotation.y = Math.atan2(-vz, vx);
      const flap = 0.15 + 0.55 * (0.5 + 0.5 * Math.sin(t * 6 + g.p * 3));
      for (const { pivot, side } of g.wings) pivot.rotation.x = -side * flap;
    }
  }

  return { update };
}

import * as THREE from 'three';
import { createSurfer } from './pelican.js';
